class Solution { public:
 int maxKDivisibleComponents(int n, vector<vector<int>>& edges, vector<int>& values, int k){
  vector<vector<int>> g(n);for(auto &e:edges){g[e[0]].push_back(e[1]);g[e[1]].push_back(e[0]);}
  vector<int> parent(n,-1),order{0};parent[0]=0;
  for(int i=0;i<(int)order.size();++i){int u=order[i];for(int v:g[u])if(parent[v]==-1){parent[v]=u;order.push_back(v);}}
  vector<long long> sum(values.begin(),values.end());int ans=0;
  for(int i=n-1;i>=0;--i){int u=order[i];if(sum[u]%k==0)++ans;else if(u!=0)sum[parent[u]]+=sum[u];}
  return ans;
 }
};
